export function getAttorneysByState(stateSlug: string): Attorney[] {
  return ATTORNEYS.filter((a) => a.state === stateSlug);
}

export function getAttorney(slug: string): Attorney | undefined {
  return ATTORNEYS.find((a) => a.slug === slug);
}
